import{_ as t,o as a,c as r,a2 as s}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Quick start","description":"","frontmatter":{},"headers":[],"relativePath":"en/quickstart.md","filePath":"en/quickstart.md","lastUpdated":null}'),n={name:"en/quickstart.md"};function o(i,e,l,p,c,h){return a(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="quick-start" tabindex="-1">Quick start <a class="header-anchor" href="#quick-start" aria-label="Permalink to &quot;Quick start&quot;">​</a></h1><p>Once installed, the app is ready on first launch.</p><h2 id="step-1-launch" tabindex="-1">Step 1: Launch <a class="header-anchor" href="#step-1-launch" aria-label="Permalink to &quot;Step 1: Launch&quot;">​</a></h2><p>Start from the desktop icon or Start Menu. The app brings up and embeds the DeepSeek Harness Web UI.</p><ul><li>On first run, if <strong>no kernel is detected</strong>, a full-screen install wizard appears.</li><li>Choose a registry (official registry.npmjs.org or the npmmirror mirror), whether to include pre-releases, and a version, then click <strong>Install kernel</strong>.</li><li>After installation the app starts dsh automatically; the Web UI appearing means you are ready.</li></ul><h2 id="step-2-tabs" tabindex="-1">Step 2: Tabs <a class="header-anchor" href="#step-2-tabs" aria-label="Permalink to &quot;Step 2: Tabs&quot;">​</a></h2><p>The frameless title bar starts with a <strong>browser-style tab strip</strong>:</p><ol><li><strong>DeepSeek UI</strong> — the embedded DeepSeek Harness main interface (default).</li><li><strong>Web chat</strong> — embeds <a href="https://chat.deepseek.com/" target="_blank" rel="noreferrer">chat.deepseek.com</a>.</li><li><strong>Usage / top-up</strong> — embeds <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">platform.deepseek.com</a> for usage and balance.</li></ol><p>These three are <strong>fixed tabs</strong>: always present, never closable. Beyond them:</p><ul><li>Links opened from a page (<code>target=_blank</code>) automatically become a <strong>dynamic tab</strong>;</li><li><strong>+</strong> in the tab strip opens a new one — by default the <strong>built-in new tab page</strong> (search box plus shortcuts), or a <strong>custom URL</strong> if you change that in Settings;</li><li>Tabs can be dragged to reorder, or dragged onto another window&#39;s light-blue overlay to <strong>move the tab into that window</strong>;</li><li>On the right: Settings, minimize / maximize / close (the terminal now lives inside Settings — see <a href="/en/settings">Settings</a>).</li></ul><div class="tip custom-block"><p class="custom-block-title">Shortcut</p><p>Hold <strong>Ctrl</strong> (<strong>Cmd</strong> on macOS) while clicking any tab to open that tab&#39;s URL in your system browser; a normal click switches in-app.</p></div><p>See <a href="/en/usage">Tabs &amp; multiple windows</a> for the full picture.</p><h2 id="step-3-optional-settings" tabindex="-1">Step 3: Optional settings <a class="header-anchor" href="#step-3-optional-settings" aria-label="Permalink to &quot;Step 3: Optional settings&quot;">​</a></h2><p>Open <strong>Settings</strong> to adjust working directory, port, appearance, kernel updates and developer mode — see <a href="/en/settings">Settings</a>.</p><h2 id="you-re-ready" tabindex="-1">You&#39;re ready <a class="header-anchor" href="#you-re-ready" aria-label="Permalink to &quot;You&#39;re ready&quot;">​</a></h2><p>Chat and use the workspace in the DeepSeek Harness Web UI. See the <a href="/en/faq">FAQ</a> if anything looks wrong.</p>',16)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
